mapper.select:
SELECT MAX(version_no)
FROM tb_kb_document_version
WHERE tenant_id = #{tenantId}
  AND document_id = #{documentId}

SELECT id
FROM tb_kb_document_version
WHERE tenant_id = #{tenantId}
  AND document_id = #{documentId}
ORDER BY version_no DESC
LIMIT 1

SELECT d.id AS document_id, dv.id AS document_version_id, d.title, d.source_type, d.category, d.effective_date, d.owner, dv.version_no, dv.status, dv.pipeline_status, dv.pipeline_error_code, dv.pipeline_error_excerpt, dv.approved_at, dv.updated_at FROM tb_kb_document d JOIN tb_kb_document_version dv ON dv.document_id = d.id AND dv.tenant_id = d.tenant_id JOIN ( SELECT document_id, MAX(version_no) AS version_no FROM tb_kb_document_version WHERE tenant_id = #{tenantId} GROUP BY document_id ) latest ON latest.document_id = dv.document_id AND latest.version_no = dv.version_no WHERE d.tenant_id = #{tenantId}
AND dv.status = #{status}
ORDER BY dv.updated_at DESC, d.id ASC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE tb_kb_document_version
SET status = #{status},
    approved_at = #{approvedAt},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND document_id = #{documentId}
  AND version_no = #{versionNo}

UPDATE tb_kb_document_version
SET pipeline_status = #{pipelineStatus},
    pipeline_error_code = #{pipelineErrorCode},
    pipeline_error_excerpt = #{pipelineErrorExcerpt},
    pipeline_updated_at = #{updatedAt},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND id = #{documentVersionId}

UPDATE tb_kb_document_version
SET status = 'archived',
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND document_id = #{documentId}
  AND version_no != #{versionNo}
  AND status = 'approved'

