DELETE FROM tb_kb_chunk_embedding
WHERE tenant_id = #{tenantId}
  AND chunk_id IN (
      SELECT id
      FROM tb_kb_chunk
      WHERE tenant_id = #{tenantId}
        AND document_version_id = #{documentVersionId}
  )

DELETE FROM tb_kb_chunk
WHERE tenant_id = #{tenantId}
  AND document_version_id = #{documentVersionId}

mapper.select:
SELECT COUNT(*)
FROM tb_kb_chunk
WHERE tenant_id = #{tenantId}
  AND document_version_id = #{documentVersionId}

